// Helper to get greetings translation
export function greetingsT(key: string, lang: string): any {
    const keys = key.split(".");
    let value: any = greetingsTranslations[lang] || greetingsTranslations["en"];
    for (const k of keys) {
        value = value?.[k];
    }
    // Fallback to English
    if (value === undefined) {
        value = greetingsTranslations["en"];
        for (const k of keys) {
            value = value?.[k];
        }
    }
    return value ?? key;
}
